helpers=r'''function selectionLabel(){if(!selected)return'NOTHING';if(selected.kind==='tile')return TILE[chunk.tiles[idx(selected.x,selected.y)]]?.label||'Tile';if(selected.kind==='object')return OBJECT[chunk.objects[selected.index]?.type]?.label||'Object';if(selected.kind==='port'){const p=chunk.ports[selected.index];return p?`${p.type.toUpperCase()} ${p.side.toUpperCase()} PORT`:'Port';}if(selected.kind==='zone'){const z=chunk.zones[selected.index];return z?`${z.type.toUpperCase()} ZONE`:'Zone';}return'NOTHING';}
function refreshSelectionUI(){if(!ui.selectionDetails)return;const label=selectionLabel();ui.selectionChip.textContent=`SELECT · ${label.toUpperCase()}`;if(!selected){ui.selectionDetails.innerHTML='Tap a tile, object marker, zone, or port to inspect it.';ui.selectionDelete.disabled=true;return;}ui.selectionDelete.disabled=false;if(selected.kind==='tile'){const type=chunk.tiles[idx(selected.x,selected.y)],d=TILE[type]||TILE.air;ui.selectionDetails.innerHTML=`<strong>${d.label}</strong><br>Tile: ${type}<br>X: ${selected.x} · Y: ${selected.y}`;return;}if(selected.kind==='object'){const o=chunk.objects[selected.index];if(!o){selected=null;return refreshSelectionUI();}const options=['generator','guaranteed','chance'].map(v=>`<option value="${v}" ${o.placement===v?'selected':''}>${v==='generator'?'Generator Choice':v[0].toUpperCase()+v.slice(1)}</option>`).join('');ui.selectionDetails.innerHTML=`<strong>${OBJECT[o.type]?.label||o.type}</strong><br>X: ${o.x} · Y: ${o.y}<div class="row"><label>Placement</label><select id="selPlacement">${options}</select></div><div class="row"><label>Chance %</label><input id="selChance" type="number" min="1" max="100" value="${o.chance||50}"></div>`;const sp=$('selPlacement'),sc=$('selChance');sp.onchange=()=>mutateSelection(()=>o.placement=sp.value);sc.onchange=()=>mutateSelection(()=>o.chance=Math.max(1,Math.min(100,Number(sc.value)||50)));return;}if(selected.kind==='port'){const p=chunk.ports[selected.index];if(!p){selected=null;return refreshSelectionUI();}const types=['hall','shaft','secret','shop'].map(v=>`<option value="${v}" ${p.type===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('');ui.selectionDetails.innerHTML=`<strong>${p.type.toUpperCase()} PORT</strong><br>Side: ${p.side} · Index: ${p.index}<div class="row"><label>Type</label><select id="selPortType">${types}</select></div><div class="row"><label>Span</label><input id="selPortSpan" type="number" min="1" max="3" value="${p.span}"></div><div class="row"><label>Depth</label><input id="selPortDepth" type="number" min="1" max="3" value="${p.depth}"></div>`;$('selPortType').onchange=e=>mutateSelection(()=>p.type=e.target.value);$('selPortSpan').onchange=e=>mutateSelection(()=>p.span=Math.max(1,Math.min(3,Number(e.target.value)||1)));$('selPortDepth').onchange=e=>mutateSelection(()=>p.depth=Math.max(1,Math.min(3,Number(e.target.value)||1)));return;}if(selected.kind==='zone'){const z=chunk.zones[selected.index];if(!z){selected=null;return refreshSelectionUI();}const types=['enemy','loot','decor'].map(v=>`<option value="${v}" ${z.type===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('');ui.selectionDetails.innerHTML=`<strong>${z.type.toUpperCase()} ZONE</strong><br>X: ${z.x} · Y: ${z.y} · ${z.w}×${z.h}<div class="row"><label>Type</label><select id="selZoneType">${types}</select></div><div class="row"><label>Min / Max</label><input id="selZoneMin" type="number" min="0" max="20" value="${z.min}"><input id="selZoneMax" type="number" min="0" max="20" value="${z.max}"></div>`;$('selZoneType').onchange=e=>mutateSelection(()=>z.type=e.target.value);$('selZoneMin').onchange=e=>mutateSelection(()=>z.min=Math.max(0,Number(e.target.value)||0));$('selZoneMax').onchange=e=>mutateSelection(()=>z.max=Math.max(0,Number(e.target.value)||0));}}
function mutateSelection(fn){pushUndo();fn();refreshSelectionUI();render();}
function selectAt(pos){const oi=chunk.objects.findIndex(o=>o.x===pos.x&&o.y===pos.y);if(oi>=0)selected={kind:'object',index:oi};else{const pi=chunk.ports.findIndex(p=>maskCells(p).some(([x,y])=>x===pos.x&&y===pos.y));if(pi>=0)selected={kind:'port',index:pi};else{let zi=-1;for(let i=(chunk.zones||[]).length-1;i>=0;i--){const z=chunk.zones[i];if(pos.x>=z.x&&pos.x<z.x+z.w&&pos.y>=z.y&&pos.y<z.y+z.h){zi=i;break;}}selected=zi>=0?{kind:'zone',index:zi}:{kind:'tile',x:pos.x,y:pos.y};}}refreshSelectionUI();render();}
function deleteSelection(){if(!selected)return;pushUndo();if(selected.kind==='tile')chunk.tiles[idx(selected.x,selected.y)]='air';else if(selected.kind==='object')chunk.objects.splice(selected.index,1);else if(selected.kind==='port')chunk.ports.splice(selected.index,1);else if(selected.kind==='zone')chunk.zones.splice(selected.index,1);selected=null;refreshSelectionUI();render();}
function drawSelectionHighlight(){if(!selected)return;ctx.save();ctx.strokeStyle='#fff59d';ctx.lineWidth=4;ctx.setLineDash([7,4]);if(selected.kind==='tile')ctx.strokeRect(selected.x*cell+4,selected.y*cell+4,cell-8,cell-8);else if(selected.kind==='object'){const o=chunk.objects[selected.index];if(o)ctx.strokeRect(o.x*cell+5,o.y*cell+5,cell-10,cell-10);}else if(selected.kind==='zone'){const z=chunk.zones[selected.index];if(z)ctx.strokeRect(z.x*cell+4,z.y*cell+4,z.w*cell-8,z.h*cell-8);}else if(selected.kind==='port'){const p=chunk.ports[selected.index];if(p)for(const [x,y] of maskCells(p))ctx.strokeRect(x*cell+5,y*cell+5,cell-10,cell-10);}ctx.restore();}
function ptRects(type,x,y){if(['air','ladder','vent','glassPartition'].includes(type))return[];if(type==='halfTop')return[[x,y,1,.5]];if(type==='halfBottom')return[[x,y+.5,1,.5]];if(type==='halfLeft')return[[x,y,.5,1]];if(type==='halfRight')return[[x+.5,y,.5,1]];if(type==='threeQuarterBR')return[[x,y,1,.5],[x,y+.5,.5,.5]];if(type==='threeQuarterBL')return[[x,y,1,.5],[x+.5,y+.5,.5,.5]];if(type==='threeQuarterTR')return[[x,y,.5,.5],[x,y+.5,1,.5]];if(type==='threeQuarterTL')return[[x+.5,y,.5,.5],[x,y+.5,1,.5]];if(type==='thinSolid')return[[x,y,1,.22]];if(type==='oneWay')return[];if(['conveyorLeft','conveyorRight','electricFloor','heatFloor','spikeFloor'].includes(type))return[[x,y+.68,1,.32]];return[[x,y,1,1]];}
function ptOverlap(ax,ay,aw,ah,r){return ax<r[0]+r[2]&&ax+aw>r[0]&&ay<r[1]+r[3]&&ay+ah>r[1];}
function ptSolidRects(x,y,w,h){const out=[],x0=Math.max(0,Math.floor(x)-1),x1=Math.min(chunk.size[0]-1,Math.ceil(x+w)+1),y0=Math.max(0,Math.floor(y)-1),y1=Math.min(chunk.size[1]-1,Math.ceil(y+h)+1);for(let ty=y0;ty<=y1;ty++)for(let tx=x0;tx<=x1;tx++)out.push(...ptRects(chunk.tiles[idx(tx,ty)],tx,ty));return out;}
function ptTouchesLadder(){if(!pt)return false;const cx=Math.floor(pt.x+pt.w/2),y0=Math.max(0,Math.floor(pt.y)),y1=Math.min(chunk.size[1]-1,Math.floor(pt.y+pt.h));for(let y=y0;y<=y1;y++)if(inBounds(cx,y)&&chunk.tiles[idx(cx,y)]==='ladder')return true;return false;}
function findPlaytestSpawn(){const marker=chunk.objects.find(o=>o.type==='spawn');if(marker)return{x:marker.x+.5-.275,y:marker.y+1-.85};for(let y=0;y<chunk.size[1]-1;y++)for(let x=1;x<chunk.size[0]-1;x++){const here=chunk.tiles[idx(x,y)],below=chunk.tiles[idx(x,y+1)];if((TILE[here]?.pass||here==='air')&&ptRects(below,x,y+1).length)return{x:x+.5-.275,y:y+1-.85};}return{x:.25,y:.15};}
function resetPlaytestPlayer(){const s=findPlaytestSpawn();pt={x:s.x,y:s.y,vx:0,vy:0,w:.55,h:.85,onGround:false,last:performance.now()};}
function startPlaytest(){if(playtesting)return;selected=null;refreshSelectionUI();playtesting=true;ui.workspace.classList.add('playtesting');ui.playtestHud.classList.remove('hidden');ui.playtest.textContent='■ STOP';resetPlaytestPlayer();render();requestAnimationFrame(playtestFrame);}
function stopPlaytest(){playtesting=false;ui.workspace.classList.remove('playtesting');ui.playtestHud.classList.add('hidden');ui.playtest.textContent='▶ TEST';for(const k in ptKeys)ptKeys[k]=false;pt=null;render();}
function movePtAxis(dx,dy){if(!pt)return;if(dx){let nx=pt.x+dx;for(const r of ptSolidRects(nx,pt.y,pt.w,pt.h))if(ptOverlap(nx,pt.y,pt.w,pt.h,r)){if(dx>0)nx=Math.min(nx,r[0]-pt.w);else nx=Math.max(nx,r[0]+r[2]);pt.vx=0;}pt.x=nx;}if(dy){const oldBottom=pt.y+pt.h;let ny=pt.y+dy;pt.onGround=false;for(const r of ptSolidRects(pt.x,ny,pt.w,pt.h))if(ptOverlap(pt.x,ny,pt.w,pt.h,r)){if(dy>0){ny=Math.min(ny,r[1]-pt.h);pt.onGround=true;}else ny=Math.max(ny,r[1]+r[3]);pt.vy=0;}if(dy>0){const x0=Math.max(0,Math.floor(pt.x)),x1=Math.min(chunk.size[0]-1,Math.floor(pt.x+pt.w));for(let tx=x0;tx<=x1;tx++)for(let ty=Math.max(0,Math.floor(oldBottom)-1);ty<=Math.min(chunk.size[1]-1,Math.floor(ny+pt.h)+1);ty++)if(chunk.tiles[idx(tx,ty)]==='oneWay'){const top=ty+.18;if(oldBottom<=top+.06&&ny+pt.h>=top){ny=Math.min(ny,top-pt.h);pt.vy=0;pt.onGround=true;}}}pt.y=ny;}}
function playtestFrame(now){if(!playtesting||!pt)return;const dt=Math.min(.033,Math.max(.001,(now-pt.last)/1000));pt.last=now;const ladder=ptTouchesLadder();pt.vx=((ptKeys.right?1:0)-(ptKeys.left?1:0))*4.2;if(ladder&&(ptKeys.up||ptKeys.down)){pt.vy=((ptKeys.down?1:0)-(ptKeys.up?1:0))*3.2;}else{pt.vy=Math.min(10,pt.vy+22*dt);if(ptKeys.jump&&pt.onGround){pt.vy=-8.2;pt.onGround=false;}}movePtAxis(pt.vx*dt,0);movePtAxis(0,pt.vy*dt);pt.x=Math.max(0,Math.min(chunk.size[0]-pt.w,pt.x));if(pt.y>chunk.size[1]+2)resetPlaytestPlayer();render();requestAnimationFrame(playtestFrame);}
function drawPlaytestPlayer(){if(!pt)return;const x=pt.x*cell,y=pt.y*cell,w=pt.w*cell,h=pt.h*cell;ctx.save();ctx.fillStyle='#75f0dc';ctx.strokeStyle='#eafffb';ctx.lineWidth=2;ctx.fillRect(x,y+h*.25,w,h*.75);ctx.strokeRect(x,y+h*.25,w,h*.75);ctx.fillStyle='#baf8ef';ctx.fillRect(x+w*.14,y,w*.72,h*.34);ctx.strokeRect(x+w*.14,y,w*.72,h*.34);ctx.restore();}
'''
